const PREFS_KEY="iie_accessibility_preferences",REPORTS_KEY_PREFIX="iie_accessibility_reports_";function safeParse(e,t){try{const r=JSON.parse(e);return null==r?t:r}catch(e){return t}}function getPreferences(){return"undefined"==typeof localStorage?{}:safeParse(localStorage.getItem(PREFS_KEY),{})}function setPreferences(e){"undefined"!=typeof localStorage&&localStorage.setItem(PREFS_KEY,JSON.stringify(e||{}))}function getReports(e){return"undefined"==typeof localStorage?[]:safeParse(localStorage.getItem(REPORTS_KEY_PREFIX+e),[])}function submitReport(e,t){if("undefined"==typeof localStorage)return null;const r=Number(t&&t.rating);if(!r||r<1||r>5)throw new Error("Report rating must be a number between 1 and 5.");const o=getReports(e),n={rating:r,category:(t.category||"other").trim(),comment:(t.comment||"").trim().slice(0,500),createdAt:(new Date).toISOString()},i=[...o,n];return localStorage.setItem(REPORTS_KEY_PREFIX+e,JSON.stringify(i)),n}function exportReports(e){return getReports(e)}function importReports(e,t){"undefined"!=typeof localStorage&&localStorage.setItem(REPORTS_KEY_PREFIX+e,JSON.stringify(t||[]))}const AccessibilityStorage={getPreferences:getPreferences,setPreferences:setPreferences,getReports:getReports,submitReport:submitReport,exportReports:exportReports,importReports:importReports};"undefined"!=typeof module&&module.exports&&(module.exports=AccessibilityStorage),"undefined"!=typeof window&&(window.AccessibilityStorage=AccessibilityStorage);